# build_helper.py - generated by build_app.bat. Keep it in the repo: the
# macOS GitHub workflow runs it too. Per-project settings live in
# build_tools/build_config.json (created on first run, safe to edit).
#
#   python build_tools/build_helper.py build [--no-obfuscate]
#   python build_tools/build_helper.py detect | analyze | requirements | gitignore
#   python build_tools/build_helper.py save <main.py> <app name> <icon 0|1>
#   python build_tools/build_helper.py icon <src.png|ico>
#   python build_tools/build_helper.py ci <path of project inside the repo>
#   python build_tools/build_helper.py export <folder for manual GitHub upload>
#
# Why scan the source: PyArmor-obfuscated code hides its imports from
# PyInstaller, so modules such as sqlite3 get left out. Starting from the
# entry script and following local imports, the plain source tells us which
# modules, local packages and data files the build needs.
import ast
import importlib.util
import json
import os
import pathlib
import re
import shutil
import subprocess
import sys
import tempfile

ROOT = pathlib.Path('.').resolve()
TOOLS = ROOT / 'build_tools'
CONFIG = TOOLS / 'build_config.json'
ICON_ICO, ICON_PNG = TOOLS / 'app_icon.ico', TOOLS / 'app_icon.png'
SKIP = {'.git', '.github', '.venv', 'venv', 'env', 'build', 'dist', 'build_tools',
        'pyi_hooks', 'pyarmor_dist', 'pyarmor_mac_dist', '__pycache__',
        'node_modules', 'site-packages', '.idea', '.vscode', 'tests', 'test'}
GUI_LIBS = {'webview', 'tkinter', 'customtkinter', 'ttkbootstrap', 'PyQt5', 'PyQt6',
            'PySide2', 'PySide6', 'wx', 'kivy', 'flet', 'pygame', 'eel', 'toga',
            'dearpygui', 'pyglet', 'arcade'}
COMMON_DATA = ['frontend', 'templates', 'static', 'assets', 'resources', 'web', 'ui', 'locales']
PATH_FUNCS = {'join', 'Path', 'PurePath', 'open', 'exists', 'isdir', 'isfile', 'listdir',
              'glob', 'scandir', 'walk', 'abspath', 'realpath', 'load', 'loadUi',
              'create_window', 'send_from_directory', 'resource_path', 'PhotoImage',
              'imread', 'Image', 'setWindowIcon', 'QIcon', 'iconbitmap', 'read_csv'}
WIN_ONLY = {'pywin32', 'pywin32-ctypes', 'pythonnet', 'clr-loader', 'clr_loader',
            'comtypes', 'pefile', 'pywinpty', 'wmi'}
DEFAULTS = {
    '_說明': {
        'app_name': '程式名稱 (輸出檔名)',
        'main_file': '主程式 (需位於專案最上層)',
        'windowed': 'auto = 偵測到 GUI 套件就隱藏主控台視窗；true / false 可強制指定',
        'onefile': 'false = 輸出資料夾 (啟動較快)；true = 單一執行檔',
        'obfuscate': 'true = 以 PyArmor 加密原始碼',
        'data': 'auto = 自動偵測要一起打包的資料夾/檔案；或填清單，例如 ["frontend", "config.json"]',
        'hidden_imports': '偵測不到、但執行時需要的模組，例如 ["babel.numbers"]',
        'excludes': '不要打包的模組，例如 ["matplotlib"]',
        'icon': 'true = 使用 build_tools/app_icon.ico (Windows) 與 app_icon.png (macOS)',
    },
    'app_name': '', 'main_file': '', 'windowed': 'auto', 'onefile': False,
    'obfuscate': True, 'data': 'auto', 'hidden_imports': [], 'excludes': [], 'icon': False,
}


def say(msg):
    print(msg, flush=True)


# ---------------------------------------------------------------- config
def load_config():
    cfg = json.loads(json.dumps(DEFAULTS))
    if CONFIG.exists():
        try:
            cfg.update(json.loads(CONFIG.read_text(encoding='utf-8-sig')))
        except (ValueError, OSError) as e:
            sys.exit('[錯誤] build_config.json 格式錯誤：%s' % e)
    cfg['_說明'] = DEFAULTS['_說明']
    return cfg


def save_config(cfg):
    TOOLS.mkdir(exist_ok=True)
    CONFIG.write_text(json.dumps(cfg, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')


def safe_name(name):
    name = re.sub(r'[\\/:*?"<>|%!^&]+', '', name).strip(' .')
    return name or 'MyApp'


# ---------------------------------------------------------------- scanning
def local_tops():
    tops = {}
    for p in ROOT.iterdir():
        if p.name in SKIP or p.name.startswith('.'):
            continue
        if p.is_file() and p.suffix == '.py':
            tops[p.stem] = [p]
        elif p.is_dir():
            files = [f for f in p.rglob('*.py')
                     if not SKIP.intersection(f.relative_to(ROOT).parts)]
            if files:
                tops[p.name] = files
    return tops


def module_name(path):
    parts = list(path.relative_to(ROOT).with_suffix('').parts)
    is_pkg = parts[-1] == '__init__'
    if is_pkg:
        parts.pop()
    return '.'.join(parts), is_pkg


def call_name(node):
    f = node.func
    return f.attr if isinstance(f, ast.Attribute) else getattr(f, 'id', '')


def path_strings(tree):
    """String constants used like file paths (call args of path functions,
    path-ish keywords, Path / 'x', or containing a separator / extension)."""
    found = set()

    def add(s):
        if isinstance(s, str) and len(s) < 260:
            found.update(c for c in re.split(r'[\\/]', s) if c and c not in '..')

    for n in ast.walk(tree):
        if isinstance(n, ast.Constant) and isinstance(n.value, str):
            if re.search(r'[\\/]|^[\w\-]+\.\w{1,5}$', n.value):
                add(n.value)
        elif isinstance(n, ast.Call):
            if call_name(n) in PATH_FUNCS:
                for a in n.args:
                    if isinstance(a, ast.Constant):
                        add(a.value)
            for kw in n.keywords:
                if kw.arg and re.search(r'folder|dir|path|url|file|icon', kw.arg) \
                        and isinstance(kw.value, ast.Constant):
                    add(kw.value.value)
        elif isinstance(n, ast.BinOp) and isinstance(n.op, ast.Div) \
                and isinstance(n.right, ast.Constant):
            add(n.right.value)
    return found


def optional_imports(tree):
    """Imports inside try/except ImportError are optional dependencies."""
    names = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Try):
            catches = {getattr(h.type, 'id', '') for h in n.handlers if h.type is not None}
            catches |= {getattr(e, 'id', '') for h in n.handlers
                        if isinstance(h.type, ast.Tuple) for e in h.type.elts}
            if catches & {'ImportError', 'ModuleNotFoundError', 'Exception'} \
                    or any(h.type is None for h in n.handlers):
                for b in n.body:
                    for m in ast.walk(b):
                        if isinstance(m, ast.Import):
                            names.update(a.name.split('.')[0] for a in m.names)
                        elif isinstance(m, ast.ImportFrom) and m.module and not m.level:
                            names.add(m.module.split('.')[0])
    return names


def scan(main_file):
    tops = local_tops()
    entry = (ROOT / main_file).resolve()
    if not entry.is_file():
        sys.exit('[錯誤] 找不到主程式：%s' % main_file)
    queue, seen, used_tops = [entry], set(), set()
    local_mods, external, optional, strings = set(), set(), set(), set()
    while queue:
        f = queue.pop()
        if f in seen:
            continue
        seen.add(f)
        mod, is_pkg = module_name(f)
        if f != entry:
            local_mods.add(mod)
        pkg = mod.split('.') if is_pkg else mod.split('.')[:-1]
        try:
            tree = ast.parse(f.read_text(encoding='utf-8-sig'))
        except (SyntaxError, UnicodeDecodeError, OSError) as e:
            if f == entry:
                sys.exit('[錯誤] 主程式無法解析：%s' % e)
            print('[提示] 略過無法解析的檔案 %s：%s' % (f.relative_to(ROOT), e), file=sys.stderr)
            continue
        strings |= path_strings(tree)
        optional |= optional_imports(tree)
        names = []
        for n in ast.walk(tree):
            if isinstance(n, ast.Import):
                names += [a.name for a in n.names]
            elif isinstance(n, ast.ImportFrom):
                if n.level:
                    base = pkg[:len(pkg) - (n.level - 1)] if n.level > 1 else pkg
                    full = '.'.join(base + ([n.module] if n.module else []))
                else:
                    full = n.module or ''
                if full:
                    names.append(full)
                    names += [full + '.' + a.name for a in n.names if a.name != '*']
        for name in names:
            top = name.split('.')[0]
            if top in tops:
                if top not in used_tops:
                    used_tops.add(top)
                    queue += tops[top]  # whole local package, incl. dynamic imports
            elif top != '__future__':
                external.add(name)
    return {'tops': tops, 'used': used_tops, 'local': local_mods,
            'external': external, 'optional': optional, 'strings': strings}


def is_module(name):
    try:
        return importlib.util.find_spec(name) is not None
    except (ImportError, ValueError, AttributeError):
        return False


def analyze(cfg):
    s = scan(cfg['main_file'])
    ext_tops = {n.split('.')[0] for n in s['external']}
    ok_tops = {t for t in ext_tops if is_module(t)}
    missing = sorted(ext_tops - ok_tops - s['optional'])
    mods = set(s['local']) | set(cfg.get('hidden_imports') or [])
    mods.update(n for n in s['external']
                if n.split('.')[0] in ok_tops and (n in ok_tops or is_module(n)))
    gui = sorted(ext_tops & GUI_LIBS)
    windowed = cfg.get('windowed', 'auto')
    windowed = bool(gui) if windowed == 'auto' else bool(windowed)
    if cfg.get('data', 'auto') == 'auto':
        data = []
        for p in sorted(ROOT.iterdir()):
            if p.name in SKIP or p.name.startswith('.') or p.suffix in ('.py', '.pyc'):
                continue
            if p.name in s['used'] or p.name == 'requirements.txt':
                continue
            if p.name in s['strings'] or (p.is_dir() and p.name in COMMON_DATA):
                data.append(p.name)
    else:
        data = [d for d in cfg['data'] if (ROOT / d).exists()]
    targets = [cfg['main_file']] + sorted(
        t + '.py' if (ROOT / (t + '.py')).is_file() else t for t in s['used'])
    return {'mods': sorted(mods), 'local': s['local'], 'missing': missing, 'gui': gui,
            'windowed': windowed, 'data': data, 'targets': targets}


# ---------------------------------------------------------------- commands
def cmd_detect():
    cfg = load_config()
    main = cfg['main_file'] if (ROOT / cfg['main_file']).is_file() else ''
    cands = []
    for p in sorted(ROOT.glob('*.py')):
        try:
            text = p.read_text(encoding='utf-8-sig', errors='replace')
        except OSError:
            continue
        if re.search(r'__name__\s*==\s*[\'"]__main__[\'"]', text) or p.stem in ('main', 'app'):
            cands.append(p.name)
    if not main:
        for pref in ('main.py', 'app.py'):
            if pref in cands:
                main = pref
                break
        else:
            main = cands[0] if len(cands) == 1 else ''
    (pathlib.Path(os.environ.get('PYBUILD_WORK', '.')) / 'candidates.txt').write_text(
        '\n'.join(cands) + '\n', encoding='utf-8')
    say('P_MAIN_FILE=' + main)
    say('P_APP_NAME=' + (cfg['app_name'] or safe_name(ROOT.name)))
    say('P_HAS_ICON=' + ('1' if ICON_ICO.is_file() else '0'))
    say('P_ICON_ON=' + ('1' if cfg.get('icon') and ICON_ICO.is_file() else '0'))
    say('P_HAS_CONFIG=' + ('1' if CONFIG.exists() else '0'))


def cmd_save(main, name, icon):
    cfg = load_config()
    cfg.update(main_file=main, app_name=safe_name(name), icon=icon == '1')
    save_config(cfg)
    say('P_APP_NAME=' + cfg['app_name'])
    # suggested GitHub repository name: ASCII only (Chinese names fall back)
    slug = lambda s: re.sub(r'[^A-Za-z0-9._-]+', '-', s).strip('-.').lower()
    say('P_REPO_NAME=' + (slug(cfg['app_name']) or slug(ROOT.name) or 'my-python-app'))


def cmd_analyze():
    cfg = load_config()
    a = analyze(cfg)
    say('P_MODE=' + ('視窗程式 (偵測到 %s)' % ', '.join(a['gui']) if a['windowed'] and a['gui']
                     else '視窗程式' if a['windowed'] else '主控台程式'))
    say('P_DATA=' + (', '.join(a['data']) or '無'))
    say('P_MISSING=' + ', '.join(a['missing']))
    say('P_MODULES=%d' % len(a['mods']))
    say('P_TARGETS=' + ' '.join(a['targets']))
    say('P_OBFUSCATE=' + ('1' if cfg.get('obfuscate', True) else '0'))
    say('P_ONEFILE=' + ('單一執行檔' if cfg.get('onefile') else '資料夾'))


def remove(path):
    if path.is_dir() and not path.is_symlink():
        shutil.rmtree(path)
    elif path.exists() or path.is_symlink():
        path.unlink()


def cmd_build(no_obfuscate=False):
    cfg = load_config()
    if not cfg['main_file']:
        sys.exit('[錯誤] build_config.json 尚未設定 main_file')
    name, plat = cfg['app_name'] or safe_name(ROOT.name), sys.platform
    label = {'win32': 'Windows', 'darwin': 'macOS'}.get(plat, plat)
    say('[1/3] 正在偵測程式使用的模組與資料檔...')
    a = analyze(cfg)
    say('      %d 個模組，資料：%s，%s' % (len(a['mods']), ', '.join(a['data']) or '無',
                                     '視窗程式' if a['windowed'] else '主控台程式'))
    dist = ROOT / 'dist'
    zip_path = dist / ('%s-%s.zip' % (name, label))
    try:  # fails when the previous build is still running
        for p in (dist / name, dist / (name + '.app'), dist / (name + '.exe'), zip_path):
            remove(p)
    except OSError as e:
        say('[錯誤] 無法刪除舊的輸出檔，%s 可能還在執行中：%s' % (name, e))
        return 4
    work = pathlib.Path(tempfile.mkdtemp(prefix='pybuild_'))
    try:
        entry, paths = ROOT / cfg['main_file'], [ROOT]
        if cfg.get('obfuscate', True) and not no_obfuscate:
            say('[2/3] 正在以 PyArmor 加密：%s' % ' '.join(a['targets']))
            r = subprocess.call([sys.executable, '-m', 'pyarmor.cli', 'gen',
                                 '-O', str(work / 'obf')] + a['targets'], cwd=str(ROOT))
            if r:
                say('[警告] PyArmor 加密失敗 (常見原因：試用版對大型檔案有限制)')
                return 3
            entry, paths = work / 'obf' / cfg['main_file'], [work / 'obf', ROOT]
        else:
            say('[2/3] 略過加密 (%s)' % ('依你的選擇' if no_obfuscate else 'obfuscate 設定為 false'))
        say('[3/3] 正在以 PyInstaller 打包 %s 版，約需 1~3 分鐘...' % label)
        args = [sys.executable, '-m', 'PyInstaller', '--noconfirm', '--log-level', 'WARN',
                '--name', name, '--distpath', str(dist), '--workpath', str(work / 'build'),
                '--specpath', str(work), '--onefile' if cfg.get('onefile') else '--onedir',
                '--windowed' if a['windowed'] else '--console']
        for p in paths:
            args += ['--paths', str(p)]
        args += ['--hidden-import=' + m for m in a['mods']]
        args += ['--exclude-module=' + m for m in cfg.get('excludes') or []]
        for d in a['data']:
            src = ROOT / d
            args += ['--add-data', '%s%s%s' % (src, os.pathsep, d if src.is_dir() else '.')]
        icon = ICON_ICO if plat == 'win32' else ICON_PNG
        if cfg.get('icon') and icon.is_file():
            args += ['--icon', str(icon)]
        r = subprocess.call(args + [str(entry)], cwd=str(ROOT))
        if r:
            say('[錯誤] PyInstaller 打包失敗，請查看上方訊息')
            return 1
    finally:
        shutil.rmtree(work, ignore_errors=True)
    app = dist / (name + '.app')
    target = app if app.exists() else dist / name if (dist / name).is_dir() else \
        next(p for p in (dist / (name + '.exe'), dist / name) if p.exists())
    if plat == 'darwin' and shutil.which('ditto'):  # keeps .app symlinks intact
        subprocess.check_call(['ditto', '-c', '-k', '--keepParent', str(target), str(zip_path)])
    else:
        shutil.make_archive(str(zip_path.with_suffix('')), 'zip', str(dist), target.name)
    say('P_OUTPUT=%s' % target)
    say('P_ZIP=%s' % zip_path)
    return 0


def cmd_requirements():
    from importlib import metadata
    if not hasattr(metadata, 'packages_distributions'):
        sys.exit(2)  # Python < 3.10: caller falls back to pip freeze
    s = scan(load_config()['main_file'])
    stdlib = getattr(sys, 'stdlib_module_names', set())
    mapping = metadata.packages_distributions()
    dists = set()
    for top in {n.split('.')[0] for n in s['external']}:
        if top not in stdlib:
            dists.update(mapping.get(top, []))
    for d in sorted(dists, key=str.lower):
        if d.lower() in WIN_ONLY:
            continue
        try:
            say('%s==%s' % (d, metadata.version(d)))
        except metadata.PackageNotFoundError:
            say(d)


def cmd_gitignore():
    # Keep build output, local data and secrets out of the repository.
    want = ['dist/', 'build/', 'pyarmor_dist/', '*.spec', '__pycache__/', '.env',
            '*.log', '*.db', '*.sqlite', '*.sqlite3']
    p = ROOT / '.gitignore'
    raw = p.read_bytes() if p.exists() else b''
    have = {l.strip() for l in raw.decode('utf-8', 'replace').splitlines()}
    add = [w for w in want if w not in have]
    if add:
        if raw and not raw.endswith(b'\n'):
            raw += b'\n'
        raw += ('# added by build_app.bat\n' + '\n'.join(add) + '\n').encode('utf-8')
        p.write_bytes(raw)
    say('      .gitignore：%s' % ('已加入 ' + ', '.join(add) if add else '已是最新'))


def cmd_icon(src):
    # Trim transparent / white margins, square it, save a multi-size ICO for
    # Windows and a 512px PNG that PyInstaller converts to .icns on macOS.
    from PIL import Image, ImageChops
    im = Image.open(src).convert('RGBA')
    w, h = im.size
    box = im.getchannel('A').point(lambda a: 255 if a > 10 else 0).getbbox()
    if box is None or box == (0, 0, w, h):
        c = im.getpixel((0, 0))
        if min(c[:3]) >= 235:
            bg = Image.new('RGB', im.size, c[:3])
            diff = ImageChops.difference(im.convert('RGB'), bg).convert('L')
            box = diff.point(lambda v: 255 if v > 20 else 0).getbbox() or box
    if box:
        im = im.crop(box)
    side = max(im.size)
    sq = Image.new('RGBA', (side, side), (0, 0, 0, 0))
    sq.paste(im, ((side - im.width) // 2, (side - im.height) // 2))
    TOOLS.mkdir(exist_ok=True)
    sq.resize((512, 512), Image.LANCZOS).save(ICON_PNG, format='PNG')
    sq.resize((256, 256), Image.LANCZOS).save(
        ICON_ICO, format='ICO', sizes=[(s, s) for s in (16, 24, 32, 48, 64, 128, 256)])
    say('      原圖 %dx%d，圖案 %dx%d → 已輸出滿版圖示' % (w, h, im.width, im.height))


def cmd_export(dest):
    # Clean copy for drag-and-drop upload on github.com (no Git needed):
    # source + build_tools, without build output, venvs, local data or secrets.
    dest = pathlib.Path(dest).resolve()
    skip_dirs = (SKIP - {'build_tools'}) | {'.github'}
    skip_files = re.compile(r'.*\.(db|sqlite3?|log|pyc|spec)$|^\.env$', re.I)
    if dest.exists():
        shutil.rmtree(dest)
    count, big = 0, []
    for p in sorted(ROOT.rglob('*')):
        rel = p.relative_to(ROOT)
        if not p.is_file() or dest in p.parents:
            continue
        if any(part in skip_dirs or part.startswith('.') for part in rel.parts[:-1]):
            continue
        if any((ROOT.joinpath(*rel.parts[:i + 1]) / 'pyvenv.cfg').exists()
               for i in range(len(rel.parts) - 1)):
            continue  # virtual environment with a custom name
        if skip_files.match(p.name) or (p.name.startswith('.') and p.name != '.gitignore'):
            continue
        (dest / rel).parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(p, dest / rel)
        count += 1
        if p.stat().st_size > 25 * 1024 * 1024:
            big.append(str(rel))
    say('P_FILES=%d' % (count + 1))  # + the workflow file added by the bat
    say('P_BIG=' + ', '.join(big))


def cmd_ci(prefix):
    # One workflow per project folder, so several projects can share a repo.
    prefix = prefix.strip().strip('/')
    slug = re.sub(r'[^A-Za-z0-9]+', '_', prefix).strip('_').lower()
    say('P_WF_FILE=' + ('build_mac_%s.yml' % slug if slug else 'build_mac.yml'))
    say('P_MARKER=' + ('[build-mac:%s]' % slug if slug else '[build-mac]'))
    say('P_PROJ_REL=' + (prefix + '/' if prefix else ''))


if __name__ == '__main__':
    argv = sys.argv[1:] or ['help']
    cmd, rest = argv[0], argv[1:]
    if cmd == 'build':
        sys.exit(cmd_build('--no-obfuscate' in rest))
    elif cmd == 'detect':
        cmd_detect()
    elif cmd == 'save':
        cmd_save(*rest[:3])
    elif cmd == 'analyze':
        cmd_analyze()
    elif cmd == 'requirements':
        cmd_requirements()
    elif cmd == 'gitignore':
        cmd_gitignore()
    elif cmd == 'icon':
        cmd_icon(rest[0])
    elif cmd == 'ci':
        cmd_ci(rest[0] if rest else '')
    elif cmd == 'export':
        cmd_export(rest[0])
    else:
        sys.exit(__doc__ or 'usage: see the header of this file')
